        )

    def recency_boost(self, metadata: Dict[str, Any]) -> float:
        ts = metadata.get("timestamp")
        if not ts:
            return 0.0
        try:
            parsed = datetime.fromisoformat(str(ts).replace("Z", "+00:00"))
        except ValueError:
            return 0.0
        age_days = max(0.0, (datetime.now(timezone.utc) - parsed).total_seconds() / 86400.0)
        return self.RECENCY_MAX_BOOST * math.exp(-age_days / self.RECENCY_HALF_LIFE_DAYS)

    def authority_boost(self, metadata: Dict[str, Any]) -> float:
        priority = metadata.get("priority", 0.0)
        try:
            priority = float(priority)
        except (TypeError, ValueError):
            priority = 0.0
        return min(1.0, max(0.0, priority)) * self.AUTHORITY_MAX_BOOST

    def rank(self, query: str, document: Document, semantic_score: float) -> float:
        """Final relevance = semantic relevance scaled by metadata signals."""
        keyword = self.keyword_boost(document.text)
        recency = self.recency_boost(document.metadata)
        authority = self.authority_boost(document.metadata)
        return semantic_score * (1.0 + keyword + recency + authority)


# --------------------------------------------------------------------------- #
# The RAG system
# --------------------------------------------------------------------------- #


class RAGSystem:
    """Filter by metadata, rank by relevance + metadata, answer with citations."""

    def __init__(self, documents: Optional[Iterable[Document]] = None) -> None:
        self.documents: List[Document] = []
        self.ranker = MetadataRanker()
        self.index = TfidfIndex()
        if documents:
            for doc in documents:
                self.add_document(doc)

    # -- indexing ----------------------------------------------------------

    def add_document(self, document: Document) -> None:
        self.documents.append(document)
        self.index.add_document(tokenize(document.text))
        self.index.finalize()  # incremental rebuild; fine for small corpora

    def load_json(self, path: str) -> int:
        """Load documents from a JSON file (list, or {"documents": [...]})."""
        with open(path, "r", encoding="utf-8") as fh:
            payload = json.load(fh)
        items = payload if isinstance(payload, list) else payload.get("documents", [])
        for item in items:
            self.add_document(Document.from_dict(item))
        return len(items)

    # -- retrieval ---------------------------------------------------------

    def retrieve(
        self,
        query: str,
        k: int = 4,
        metadata_filter: Optional[Dict[str, Any]] = None,
    ) -> List[Dict[str, Any]]:
        """Metadata-filter the pool, then rank by relevance + metadata signals."""
        pool = apply_metadata_filter(self.documents, metadata_filter)
        if not pool:
            return []

        query_vec = self.index.vector(tokenize(query))
        scored: List[Tuple[Document, float, float]] = []
        for doc in pool:
            doc_vec = self.index.vector(tokenize(doc.text))
            semantic = cosine_similarity(query_vec, doc_vec)
            final = self.ranker.rank(query, doc, semantic)
            scored.append((doc, final, semantic))

        scored.sort(key=lambda item: item[1], reverse=True)

        return [
            {
                "document": doc,
                "score": round(final, 6),
                "semantic": round(semantic, 6),
            }
            for doc, final, semantic in scored[:k]
        ]

    # -- grounded answering --------------------------------------------------

    def answer(
        self,
        query: str,
        k: int = 4,
        metadata_filter: Optional[Dict[str, Any]] = None,
        results: Optional[List[Dict[str, Any]]] = None,
    ) -> Dict[str, Any]:
        """Grounded, citation-aware answer built from the top retrieved document."""
        results = results if results is not None else self.retrieve(
            query, k=k, metadata_filter=metadata_filter
        )
        if not results:
            return {
                "answer": "I don't have enough information.",
                "confidence": 0.0,
                "sources": [],
                "results": [],
            }

        top_doc = results[0]["document"]
        sentence = _best_sentence(top_doc.text, query)
        source = top_doc.metadata.get("source", "unknown")
        return {
            "answer": f"{sentence} (source: {source})",
            "confidence": round(min(0.95, results[0]["score"]), 4),
            "sources": [
                {
                    "source": r["document"].metadata.get("source", "unknown"),
                    "score": r["score"],
                }
                for r in results
            ],
            "results": results,
        }


def _best_sentence(text: str, query: str) -> str:
    """Pick the sentence from a document that overlaps most with the query."""
    sentences = re.split(r"(?<=[.!?])\s+", text.strip()) or [text]
    query_terms = set(tokenize(query))
    best, best_score = sentences[0], -1
    for sentence in sentences:
        overlap = len(query_terms & set(tokenize(sentence)))
        if overlap > best_score:
            best, best_score = sentence, overlap
    return best.strip()


# --------------------------------------------------------------------------- #
# Demo + CLI
# --------------------------------------------------------------------------- #


def build_sample_system() -> RAGSystem:
    system = RAGSystem()
    for item in SAMPLE_DOCUMENTS:
        system.add_document(Document.from_dict(item))
    return system


def run_demo() -> None:
    system = build_sample_system()
    print("=" * 74)
    print("METADATA-AWARE RAG DEMO")
    print("=" * 74)
    print(f"Indexed {len(system.documents)} documents.\n")

    cases = [
        (
            "How do I log a query to the MLOps server?",
            None,
            "Keyword ranking: 'upload' / 'post-retrieval logging' docs should lead.",
        ),
        (
            "How are secrets handled?",
            {"category": "security"},
            "Metadata filter: only security documents are eligible.",
        ),
        (
            "What API limits apply?",
            {"tags": ["rate-limit"]},
            "Metadata filter by tag.",
        ),
    ]

    for query, mfilter, note in cases:
        print("-" * 74)
        print(f"QUERY: {query}")
        print(f"NOTE : {note}")
        if mfilter:
            print(f"FILTER: {json.dumps(mfilter)}")
        results = system.retrieve(query, k=3, metadata_filter=mfilter)
        if not results:
            print("  (no documents matched the metadata filter)")
        for rank, result in enumerate(results, start=1):
            doc = result["document"]
            print(
                f"  #{rank} score={result['score']:.4f} semantic={result['semantic']:.4f} "
                f"source={doc.metadata.get('source')!r} category={doc.metadata.get('category')!r}"
            )
        answer = system.answer(query, k=3, metadata_filter=mfilter, results=results)
        print(f"  ANSWER     : {answer['answer']}")
        print(f"  CONFIDENCE : {answer['confidence']}")

    # Assertion: for the MLOps logging query the default RAG DB entries must lead.
    results = system.retrieve("how do I log a query to the MLOps server", k=3)
    top_source = results[0]["document"].metadata.get("source")
    assert top_source == "rag-skill/default-db", f"expected default-db on top, got {top_source}"
    print("-" * 74)
    print("DEMO OK: default RAG DB entry ranked first for the MLOps logging query.")


def main(argv: Optional[Sequence[str]] = None) -> int:
    parser = argparse.ArgumentParser(description="Metadata-aware RAG system")
    parser.add_argument("--query", help="Run a single query instead of the demo.")
    parser.add_argument("--k", type=int, default=4, help="Number of results to return.")
    parser.add_argument(
        "--filter",
        default=None,
        help='JSON metadata filter, e.g. \'{"category": "security"}\'',
    )
    parser.add_argument(
        "--docs", default=None, help="Optional JSON file of documents to index."
    )
    args = parser.parse_args(argv)

    if args.query is None:
        run_demo()
        return 0

    if args.docs:
        system = RAGSystem()
        loaded = system.load_json(args.docs)
        print(f"Loaded {loaded} documents from {args.docs}.")
    else:
        system = build_sample_system()

    mfilter = json.loads(args.filter) if args.filter else None
    result = system.answer(args.query, k=args.k, metadata_filter=mfilter)
    print(json.dumps(result, indent=2, default=str))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

