#!/usr/bin/env python3
"""
Metadata-Aware RAG System
=========================

A dependency-free Retrieval-Augmented Generation (RAG) implementation that
uses document **metadata for filtering** and **ranking** documents based on
relevance to user queries.

Pipeline
--------
1. Index: each document is stored with rich metadata (source, category, tags,
   timestamp, priority). A sparse TF-IDF vector index (standard library only)
   provides the semantic backbone for relevance.
2. Filter: retrieval is restricted to documents whose metadata matches a
   filter, e.g. {"category": "security"} or {"tags": ["api"]}. Filtering runs
   before ranking so out-of-scope documents never surface.
3. Rank: final score = semantic relevance * (1 + priority_boost
   + recency_boost + authority_boost), where the boosts come from metadata
   fields. Ranking is fully configurable per document metadata.
4. Answer: a grounded, citation-aware answer is generated from the top
   retrieved document with a confidence score.

Usage
-----
    python rag_metadata_system.py                            # built-in demo
    python rag_metadata_system.py --query "secrets" \
        --filter '{"category": "security"}' --k 3
"""

from __future__ import annotations

