# --------------------------------------------------------------------------- #
# Core data structures
# --------------------------------------------------------------------------- #


class Document:
    """A text chunk together with its metadata (source, category, tags, ...)."""

    __slots__ = ("text", "metadata")

    def __init__(self, text: str, metadata: Optional[Dict[str, Any]] = None):
        self.text = text
        self.metadata = dict(metadata or {})

    def to_dict(self) -> Dict[str, Any]:
        return {"text": self.text, "metadata": self.metadata}

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "Document":
        return cls(text=data["text"], metadata=data.get("metadata"))

    def __repr__(self) -> str:
        return f"Document(source={self.metadata.get('source', '?')!r})"


_TOKEN_RE = re.compile(r"[a-z0-9]+")


def tokenize(text: str) -> List[str]:
    """Lowercase alphanumeric tokens (dependency-free tokenizer)."""
    return _TOKEN_RE.findall(text.lower())


# --------------------------------------------------------------------------- #
# Semantic index (sparse TF-IDF vectors + cosine similarity)
# --------------------------------------------------------------------------- #


class TfidfIndex:
    """Sparse TF-IDF index over the corpus, used as the embedding backbone."""

    def __init__(self) -> None:
        self._doc_freqs: Counter = Counter()
        self.idf: Dict[str, float] = {}
        self.num_docs = 0

    def add_document(self, tokens: Sequence[str]) -> None:
        for term in set(tokens):
            self._doc_freqs[term] += 1
        self.num_docs += 1

    def finalize(self) -> None:
        n = self.num_docs
        self.idf = {
            term: math.log((1.0 + n) / (1.0 + df)) + 1.0
            for term, df in self._doc_freqs.items()
        }

    def vector(self, tokens: Sequence[str]) -> Dict[str, float]:
        """TF-IDF vector for a token list (sparse dict term -> weight)."""
        if not tokens:
            return {}
        tf = Counter(tokens)
        max_tf = float(max(tf.values()))
        return {
            term: (0.5 + 0.5 * count / max_tf) * self.idf.get(term, 0.0)
            for term, count in tf.items()
            if term in self.idf
        }


def cosine_similarity(vec_a: Dict[str, float], vec_b: Dict[str, float]) -> float:
    """Cosine similarity between two sparse vectors."""
    if not vec_a or not vec_b:
        return 0.0
    dot = 0.0
    for term, weight in vec_a.items():
        other = vec_b.get(term)
        if other:
            dot += weight * other
    if dot == 0.0:
        return 0.0
    norm_a = math.sqrt(sum(w * w for w in vec_a.values()))
    norm_b = math.sqrt(sum(w * w for w in vec_b.values()))
    if norm_a == 0.0 or norm_b == 0.0:
        return 0.0
    return dot / (norm_a * norm_b)


# --------------------------------------------------------------------------- #
# Metadata filtering
# --------------------------------------------------------------------------- #


def apply_metadata_filter(
    documents: Sequence[Document], filters: Optional[Dict[str, Any]]
) -> List[Document]:
    """Keep only documents whose metadata matches every filter entry.

    A filter value may be a scalar (exact match) or a list/tuple/set
    (membership). Missing metadata keys never match, so filters are strict.
    """
    if not filters:
        return list(documents)
    kept: List[Document] = []
    for doc in documents:
        matches = True
        for key, expected in filters.items():
            actual = doc.metadata.get(key)
            if isinstance(expected, (list, tuple, set)):
                if actual not in expected:
                    matches = False
                    break
            elif actual != expected:
                matches = False
                break
        if matches:
            kept.append(doc)
    return kept


# --------------------------------------------------------------------------- #
# Metadata-aware ranking
# --------------------------------------------------------------------------- #


class MetadataRanker:
    """Blends semantic relevance with metadata signals.

    final_score = semantic * (1 + priority_boost + recency_boost + authority_boost)

    * priority_boost: derived from the "priority" metadata field (0.0-1.0).
    * recency_boost:  derived from the "timestamp" metadata field; fresher
      documents score higher.
    * authority_boost: derived from the "source" metadata field; trusted
      sources (e.g. official runbooks) score higher.
    """

    PRIORITY_MAX_BOOST = 0.20
    RECENCY_HALF_LIFE_DAYS = 120.0
    RECENCY_MAX_BOOST = 0.05
    AUTHORITY_SOURCES = ("security-policy.md", "api-guide.md")
    AUTHORITY_MAX_BOOST = 0.05

    def priority_boost(self, metadata: Dict[str, Any]) -> float:
        priority = metadata.get("priority", 0.0)
        try:
            priority = float(priority)
        except (TypeError, ValueError):
            priority = 0.0
        return min(1.0, max(0.0, priority)) * self.PRIORITY_MAX_BOOST

    def recency_boost(self, metadata: Dict[str, Any]) -> float:
        ts = metadata.get("timestamp")
        if not ts:
            return 0.0
        try:
            parsed = datetime.fromisoformat(str(ts).replace("Z", "+00:00"))
        except ValueError:
            return 0.0
        age_days = max(0.0, (datetime.now(timezone.utc) - parsed).total_seconds() / 86400.0)
        return self.RECENCY_MAX_BOOST * math.exp(-age_days / self.RECENCY_HALF_LIFE_DAYS)

    def authority_boost(self, metadata: Dict[str, Any]) -> float:
        source = metadata.get("source")
        if source in self.AUTHORITY_SOURCES:
            return self.AUTHORITY_MAX_BOOST
        return 0.0

    def rank(self, query: str, document: Document, semantic_score: float) -> float:
        """Final relevance = semantic relevance scaled by metadata signals."""
        priority = self.priority_boost(document.metadata)
        recency = self.recency_boost(document.metadata)
        authority = self.authority_boost(document.metadata)
        return semantic_score * (1.0 + priority + recency + authority)


# --------------------------------------------------------------------------- #
# The RAG system
# --------------------------------------------------------------------------- #


class RAGSystem:
    """Filter by metadata, rank by relevance + metadata, answer with citations."""

    def __init__(self, documents: Optional[Iterable[Document]] = None) -> None:
        self.documents: List[Document] = []
        self.ranker = MetadataRanker()
        self.index = TfidfIndex()
        if documents:
            for doc in documents:
                self.add_document(doc)

    # -- indexing ----------------------------------------------------------

    def add_document(self, document: Document) -> None:
        self.documents.append(document)
        self.index.add_document(tokenize(document.text))
        self.index.finalize()  # incremental rebuild; fine for small corpora

    def load_json(self, path: str) -> int:
        """Load documents from a JSON file (list, or {"documents": [...]})."""
        with open(path, "r", encoding="utf-8") as fh:
            payload = json.load(fh)
        items = payload if isinstance(payload, list) else payload.get("documents", [])
        for item in items:
            self.add_document(Document.from_dict(item))
        return len(items)

    # -- retrieval ---------------------------------------------------------

    def retrieve(
        self,
        query: str,
        k: int = 4,
        metadata_filter: Optional[Dict[str, Any]] = None,
    ) -> List[Dict[str, Any]]:
        """Metadata-filter the pool, then rank by relevance + metadata signals."""
        pool = apply_metadata_filter(self.documents, metadata_filter)
        if not pool:
            return []

        query_vec = self.index.vector(tokenize(query))
        scored: List[Tuple[Document, float, float]] = []
        for doc in pool:
            doc_vec = self.index.vector(tokenize(doc.text))
            semantic = cosine_similarity(query_vec, doc_vec)
            final = self.ranker.rank(query, doc, semantic)
            scored.append((doc, final, semantic))

        scored.sort(key=lambda item: item[1], reverse=True)

        return [
            {
                "document": doc,
                "score": round(final, 6),
                "semantic": round(semantic, 6),
            }
            for doc, final, semantic in scored[:k]
        ]

    # -- grounded answering --------------------------------------------------

    def answer(
        self,
        query: str,
        k: int = 4,
        metadata_filter: Optional[Dict[str, Any]] = None,
        results: Optional[List[Dict[str, Any]]] = None,
    ) -> Dict[str, Any]:
        """Grounded, citation-aware answer built from the top retrieved document."""
        results = results if results is not None else self.retrieve(
            query, k=k, metadata_filter=metadata_filter
        )
        if not results:
            return {
                "answer": "I don't have enough information.",
                "confidence": 0.0,
                "sources": [],
                "results": [],
            }

        top_doc = results[0]["document"]
        sentence = _best_sentence(top_doc.text, query)
        source = top_doc.metadata.get("source", "unknown")
        return {
            "answer": f"{sentence} (source: {source})",
            "confidence": round(min(0.95, results[0]["score"]), 4),
            "sources": [
                {
                    "source": r["document"].metadata.get("source", "unknown"),
                    "score": r["score"],
                }
                for r in results
            ],
            "results": results,
        }


def _best_sentence(text: str, query: str) -> str:
    """Pick the sentence from a document that overlaps most with the query."""
    sentences = re.split(r"(?<=[.!?])\s+", text.strip()) or [text]
    query_terms = set(tokenize(query))
    best, best_score = sentences[0], -1
    for sentence in sentences:
        overlap = len(query_terms & set(tokenize(sentence)))
        if overlap > best_score:
            best, best_score = sentence, overlap
    return best.strip()


